<nav class="topic-nav" aria-label="认证审核状态"><a href="<?= e(adminUrl('verifications')) ?>" class="<?= !getValue('status')?'active':'' ?>">全部认证</a><?php foreach(['pending'=>'待审核','approved'=>'已通过','rejected'=>'已驳回'] as $state=>$label): ?><a href="<?= e(adminUrl('verifications',['status'=>$state])) ?>" class="<?= getValue('status')===$state?'active':'' ?>"><?= $label ?></a><?php endforeach ?></nav>
<section class="panel review-panel"><div class="result-summary">共 <?= (int)$result['total'] ?> 条认证申请 · 证件材料仅管理员与本人可查看</div>
<?php foreach($items as $item): $files=verificationFiles((int)$item['id']); ?>
<article class="review-row verification-review" data-verification-id="<?= $item['id'] ?>"><div class="listing-title"><span class="verification-tag <?= e($item['status']) ?>"><?= e(verificationStatus($item)) ?></span><h2><?= e($item['subject_name']) ?></h2><span class="member-badge"><?= verificationType($item['type']) ?></span></div><div class="listing-meta"><span>账号：<?= e($item['username']) ?><?= !$item['user_enabled']?'（已停用）':'' ?> · 第 <?= (int)$item['revision'] ?> 次提交</span><span><?= e($item['submitted_at']) ?></span></div><div class="verification-review-documents"><?php foreach(verificationRoles($item['type']) as $role=>$label): if(!isset($files[$role])) continue; $file=$files[$role]; ?><a href="<?= e(adminUrl('document',['id'=>$file['id']])) ?>" target="_blank" rel="noopener"><img src="<?= e(adminUrl('document',['id'=>$file['id']])) ?>" alt="<?= e($label) ?>"><span><?= e($label) ?> · 查看材料</span></a><?php endforeach ?></div><?php if($item['rejection_reason']): ?><p class="rejection">驳回原因：<?= e($item['rejection_reason']) ?></p><?php endif ?><div class="review-actions"><?php if($item['status']==='pending'): ?><form method="post"><?= csrfField() ?><input type="hidden" name="id" value="<?= $item['id'] ?>"><input type="hidden" name="revision" value="<?= $item['revision'] ?>"><input type="hidden" name="action" value="approve"><button class="button small">认证通过</button></form><details><summary class="button button-outline small danger">驳回认证</summary><form method="post" class="reject-form"><?= csrfField() ?><input type="hidden" name="id" value="<?= $item['id'] ?>"><input type="hidden" name="revision" value="<?= $item['revision'] ?>"><input type="hidden" name="action" value="reject"><label>驳回原因<input name="reason" minlength="2" maxlength="500" required placeholder="说明需要修改的材料"></label><button class="button small">确认驳回</button></form></details><?php endif ?><form method="post" data-confirm="确定删除这条认证及证件材料？会员账号和发布信息会保留，已通过的认证标识将取消。操作前会保存本地恢复备份。"><?= csrfField() ?><input type="hidden" name="id" value="<?= (int)$item['id'] ?>"><input type="hidden" name="revision" value="<?= (int)$item['revision'] ?>"><input type="hidden" name="status" value="<?= e($item['status']) ?>"><input type="hidden" name="action" value="delete"><button class="button button-outline small danger">删除认证</button></form></div></article>
<?php endforeach ?><?php if(!$items): ?><div class="empty-state"><span>此状态下暂无认证申请</span></div><?php endif ?><?php pagination($result) ?></section>
